const VARIANT_LABELS = ['spot', 'keywords', 'trap', 'extra'];

function compactList(value) {
  if (Array.isArray(value)) return value.map((item) => String(item || '').trim()).filter(Boolean);
  return String(value || '').split(';').map((item) => item.trim()).filter(Boolean);
}

function polishMedicalTerminology(value = '') {
  return String(value || '')
    .replace(/\bN\.\s*fibularis\s+communis\b/giu, 'nervus fibularis communis')
    .replace(/\bn\.\s*fibularis\s+communis\b/giu, 'nervus fibularis communis')
    .replace(/\bN\.\s*intercostobrachialis\b/giu, 'nervus intercostobrachialis')
    .replace(/\bn\.\s*intercostobrachialis\b/giu, 'nervus intercostobrachialis')
    .replace(/\bN\.\s*oculomotorius\b/giu, 'nervus oculomotorius')
    .replace(/\bn\.\s*oculomotorius\b/giu, 'nervus oculomotorius')
    .replace(/\bN\.\s*abducens\b/giu, 'nervus abducens')
    .replace(/\bn\.\s*abducens\b/giu, 'nervus abducens')
    .replace(/\bN\.\s*axillaris\b/giu, 'nervus axillaris')
    .replace(/\bn\.\s*axillaris\b/giu, 'nervus axillaris')
    .replace(/\bN\.\s*tibialis\b/giu, 'nervus tibialis')
    .replace(/\bn\.\s*tibialis\b/giu, 'nervus tibialis')
    .replace(/\bV\.\s*saphena\s+magna\b/giu, 'vena saphena magna')
    .replace(/\bv\.\s*saphena\s+magna\b/giu, 'vena saphena magna')
    .replace(/\bV\.\s*saphena\s+parva\b/giu, 'vena saphena parva')
    .replace(/\bv\.\s*saphena\s+parva\b/giu, 'vena saphena parva')
    .replace(/\bA\.\s*communicans\s+posterior\b/giu, 'arteria communicans posterior')
    .replace(/\ba\.\s*communicans\s+posterior\b/giu, 'arteria communicans posterior')
    .replace(/\bS\.\s*pneumoniae\b/gu, 'Streptococcus pneumoniae')
    .replace(/\bS\.\s*aureus\b/gu, 'Staphylococcus aureus')
    .replace(/\bS\.\s*pyogenes\b/gu, 'Streptococcus pyogenes')
    .replace(/\bH\.\s*influenzae\b/gu, 'Haemophilus influenzae')
    .replace(/\bM\.\s*catarrhalis\b/gu, 'Moraxella catarrhalis')
    .replace(/\bN\.\s*meningitidis\b/gu, 'Neisseria meningitidis')
    .replace(/\bC\.\s*difficile\b/gu, 'Clostridioides difficile')
    .replace(/\bC\.\s*tetani\b/gu, 'Clostridium tetani')
    .replace(/\bV\.\s*cholerae\b/gu, 'Vibrio cholerae')
    .replace(/\bLikefaksiyon\s+nekrozu\b/giu, 'sıvılaşma nekrozu')
    .replace(/\bLikefaksiyon\b/giu, 'sıvılaşma')
    .replace(/\bSurfactan(?=\b|[ıiuü]n|[ıiuü]nda|[ıiuü]nde)/giu, 'surfaktan')
    .replace(/\bApe\s+hand\b/giu, 'maymun eli')
    .replace(/\bRed\s+man\/sendromu\b/giu, 'kızarma (red man) sendromu')
    .replace(/\s*→\s*/g, ', ')
    .replace(/\s+/g, ' ')
    .trim();
}

function capitalizeTerminologyLead(value = '') {
  return String(value || '').replace(/^(nervus|arteria|vena|intravenöz|kızarma)\b/u, (match) => match.charAt(0).toLocaleUpperCase('tr') + match.slice(1));
}

function cleanText(value = '') {
  return capitalizeTerminologyLead(polishMedicalTerminology(value).replace(/\s+/g, ' ').trim());
}

function cleanSentence(value = '') {
  const text = polishGeneratedLead(value);
  if (!text) return '';
  return /[.!?]$/u.test(text) ? text : `${text}.`;
}

function polishQuestionPhrasing(value = '') {
  return cleanText(value)
    .replace(/\bilk seçenek antibiyotik sıklıkla nedir\b/giu, 'ilk tercih edilen antibiyotik nedir')
    .replace(/\bilk seçenek tedavi sıklıkla nedir\b/giu, 'ilk tercih edilen tedavi nedir')
    .replace(/\bilk seçenek\s+(.+?)\s+sıklıkla nedir\b/giu, 'ilk tercih edilen $1 nedir')
    .replace(/\bilk seçenek\b/giu, 'ilk tercih edilen')
    .replace(/\bsıklıkla nedir\b/giu, 'nedir')
    .replace(/\bhangi temel etkiyi yapar\b/giu, 'temel etkisi nedir')
    .replace(/\bhangi başlık öncelikle düşünülür\b/giu, 'hangi kavram öncelikle düşünülür')
    .replace(/\bhangi cevabı destekler\b/giu, 'hangi yanıta götürür')
    .replace(/\bhangi kavrama yönlendirir:\s*/giu, 'hangi kavramı düşündürür: ')
    .replace(/\bpaterni en çok hangi kavramı düşündürür\b/giu, 'birlikteliği hangi kavramı düşündürür')
    .replace(/\bseçeneğini dışlatan\b/giu, 'seçeneğini dışlayan')
    .replace(/\bhangi ayrım belirleyicidir\b/giu, 'hangi ayırıcı nokta belirleyicidir')
    .replace(/\btedavinin ilk temel basamağı\b/giu, 'tedavide ilk temel basamak')
    .replace(/\btemel antibiyotik grubu nedir\b/giu, 'tercih edilen antibiyotik grubu hangisidir')
    .replace(/\btedavi seçeneklerinden biri nedir\b/giu, 'tedavi seçeneklerinden biri hangisidir')
    .replace(/\btipik grafi bulgusu nedir\b/giu, 'tipik grafi bulgusu hangisidir')
    .replace(/\btipik histoloji nedir\b/giu, 'tipik histolojik bulgu nedir')
    .replace(/\bklasik ilk seçenek nedir\b/giu, 'klasik ilk tercih nedir')
    .replace(/\bklasik ilaç nedir\b/giu, 'klasik tedavi ilacı hangisidir')
    .replace(/\bilk tercih görüntüleme nedir\b/giu, 'ilk tercih edilen görüntüleme yöntemi hangisidir')
    .replace(/\bilk tedavi nedir\b/giu, 'ilk tedavi basamağı nedir')
    .replace(/\bilk tedavi yaklaşımı nedir\b/giu, 'ilk tedavi yaklaşımı nasıl olmalıdır')
    .replace(/\btedavisinde ilk yaklaşım nedir\b/giu, 'tedavisinde ilk yaklaşım nasıl olmalıdır')
    .replace(/\bantidotal yaklaşım nedir\b/giu, 'antidotal yaklaşım nasıl olmalıdır')
    .replace(/\bacil tedavi nedir\b/giu, 'acil tedavi basamağı nedir')
    .replace(/\bkesin tedavi nedir\b/giu, 'kesin tedavi basamağı nedir')
    .replace(/\bmedikal tedavi nedir\b/giu, 'medikal tedavi seçeneği nedir')
    .replace(/\bbeklenen nekroz tipi nedir\b/giu, 'beklenen nekroz tipi hangisidir')
    .replace(/\bnekroz tipi nedir\b/giu, 'beklenen nekroz tipi hangisidir')
    .replace(/\s+/g, ' ')
    .trim();
}

function cleanQuestion(value = '') {
  const text = polishGeneratedLead(polishQuestionPhrasing(value));
  if (!text) return '';
  return /[?]$/u.test(text) ? text : `${text.replace(/[.!]+$/u, '')}?`;
}

function keywordItems(keywords = []) {
  return keywords.slice(0, 4).map((item) => cleanText(item)).filter(Boolean);
}

function joinTurkishList(items = [], connector = 've') {
  const cleanItems = items.map((item) => cleanText(item)).filter(Boolean);
  if (!cleanItems.length) return '';
  if (cleanItems.length === 1) return cleanItems[0];
  if (cleanItems.length === 2) return `${cleanItems[0]} ${connector} ${cleanItems[1]}`;
  return `${cleanItems.slice(0, -1).join(', ')} ${connector} ${cleanItems[cleanItems.length - 1]}`;
}

function readableKeywordPhrase(keywords = []) {
  return joinTurkishList(keywordItems(keywords));
}

function readableKeywordChain(keywords = []) {
  return readableKeywordPhrase(keywords);
}

function trimSentenceEnd(value = '') {
  return cleanText(value).replace(/[.!?]+$/u, '').trim();
}

function capitalizeSentenceLead(value = '') {
  const text = cleanText(value);
  if (!text) return '';
  return text.charAt(0).toLocaleUpperCase('tr') + text.slice(1);
}

function polishGeneratedLead(value = '') {
  const text = cleanText(value);
  if (!text) return '';
  if (/^(hCG|pH|PaO|PaCO|PaO₂|PaCO₂|Na\+|Na⁺|K\+|K⁺|HCO|Ig|anti-|Anti-|β|α|\d)/u.test(text)) return text;
  return text.charAt(0).toLocaleUpperCase('tr') + text.slice(1);
}

function answerLabel(topic = {}) {
  const mainAnswer = trimSentenceEnd(topic.mainAnswer || '');
  const topicName = trimSentenceEnd(topic.topic || '');
  if (!mainAnswer) return topicName;

  const answerLower = mainAnswer.toLocaleLowerCase('tr');
  const isYesNoAnswer = /^(evet|hayır|hayir)\b/u.test(answerLower);
  const isLongProcessAnswer = mainAnswer.length > 86 && topicName;
  const asksDiagnosticCue = /\b(tanı|sendrom|hastalık|istismar|patern|nekroz|lezyon|etken|mekanizma|toksisite|zehirlenme|travma)\b/iu.test(topicName);

  if ((isYesNoAnswer || isLongProcessAnswer) && asksDiagnosticCue) return topicName;
  return mainAnswer || topicName;
}

function cuePhraseFromKeywords(keywords = [], limit = 4) {
  return joinTurkishList(keywordItems(keywords).slice(0, limit));
}

function supportCuePhrase(keywords = []) {
  const items = keywordItems(keywords);
  if (items.length <= 1) return '';
  return joinTurkishList(items.slice(1, 4));
}

function buildKeywordBack(topic, keywords, topicIndex = 0) {
  const answer = answerLabel(topic);
  const cues = cuePhraseFromKeywords(keywords);
  const cueLead = polishGeneratedLead(cues);
  if (!answer && !cues) return '';
  if (!cues) return cleanSentence(answer);
  if (!answer) return cleanSentence(polishGeneratedLead(`Belirleyici patern: ${cues}`));

  const variants = [
    `${answer}. ${cueLead} birlikteliği bu yanıtı destekler`,
    `${answer}. Temel ipuçları ${cues} şeklindedir`,
    `${answer}. ${cueLead} birlikte değerlendirildiğinde bu sonuç öne çıkar`,
    `${answer}. Ayırıcı patern ${cues} birlikteliğidir`,
  ];
  return cleanSentence(polishGeneratedLead(variants[topicIndex % variants.length]));
}

